/* Fictional, internally consistent teaching vehicle: transverse petrol R4 MPI,
   DOHC 16V, belt timing, front-wheel drive, manual transmission, rear multi-link. */
'use strict';
(()=>{
const parts=[];
const cats={body:'NADWOZIE I OŚWIETLENIE',engine:'OSPRZĘT SILNIKA',internals:'WNĘTRZE SILNIKA',cabin:'KABINA I BAGAŻNIK',chassis:'NAPĘD, HAMULCE I ZAWIESZENIE',fuel:'PALIWO I WYDECH'};
function P(id,name,cat,description,how,inspect,extra={}){parts.push({id,name,cat,description,how,check:inspect?inspect.split('|'):['Oceń stan i zamocowanie elementu.','Niepokojące objawy zapisz do dalszego sprawdzenia.'],tip:extra.tip||'Model pokazuje zasadę działania. Wymiary, sposób mocowania i zakres ruchu są uproszczone.',...extra});}
P('structure','Podłoga i konstrukcja','body','Nadwozie samonośne przenosi obciążenia i utrzymuje geometrię samochodu. Progi, podłoga oraz słupki tworzą wspólną strukturę.','Zwróć uwagę, że odpięcie poszycia odsłania elementy nośne. To one przenoszą siły pomiędzy zawieszeniem a kabiną.','Obejrzyj korozję i ślady napraw.|Stan elementów nośnych oceń na podnośniku.',{family:'structure'});
P('roof','Dach','body','Usztywnia górną część kabiny i osłania pasażerów. W tym modelu można go odsunąć, aby obejrzeć wnętrze.','Wybierz wnętrze albo odsuń dach. Słupki pozostają częścią konstrukcji.','Obejrzyj lakier, uszczelki i ślady nieszczelności.',{family:'structure'});
P('hood','Maska','body','Osłania komorę silnika. Jej zamek ma zabezpieczenie przed przypadkowym otwarciem.','Otwórz maskę na zawiasach przy przedniej szybie. Przycisk „Odsuń” pozwala obejrzeć jej spód.','Sprawdź spasowanie i zamek.|Obejrzyj śruby mocowań i wewnętrzne wzmocnienia.',{family:'panels',motion:'Otwórz / zamknij maskę'});
P('trunk','Pokrywa bagażnika','body','W sedanie otwiera się oddzielna pokrywa bagażnika; tylna szyba pozostaje nieruchoma.','Unieś pokrywę i porównaj ją z nieruchomą szybą. To cecha trzybryłowego nadwozia.','Sprawdź zamek, zawiasy i uszczelkę.|Poszukaj wilgoci pod podłogą.',{family:'panels',motion:'Otwórz / zamknij bagażnik'});
P('front-bumper','Zderzak przedni','body','Zewnętrzna osłona kształtuje przód i chroni drobne elementy. Wzmocnienie oraz absorbery pod osłoną przenoszą część energii uderzenia.','Odsuń osłonę, żeby odsłonić belkę zderzeniową i chłodnicę.','Obejrzyj mocowania, pęknięcia i spasowanie.',{family:'panels'});
P('rear-bumper','Zderzak tylny','body','Osłona tylnego pasa kryje mocowania i wzmocnienie. Sama powłoka z tworzywa nie stanowi całej ochrony zderzeniowej.','Odsuń ją, aby zobaczyć belkę za poszyciem.','Sprawdź szczeliny i ślady napraw.',{family:'panels'});
P('grille','Kratka wlotu powietrza','body','Dopuszcza powietrze do wymienników ciepła i chroni je przed większymi przedmiotami.','Po odsunięciu kratki widać chłodnicę. To inne zadanie niż filtracja powietrza zasysanego do silnika.','Obejrzyj uszkodzenia i drożność.',{family:'cooling'});
P('windshield','Szyba przednia','body','Klejona, laminowana szyba zapewnia widoczność i współpracuje ze strukturą nadwozia.','Odsunięcie szkła pozwala obejrzeć kokpit i podszybie.','Szukaj pęknięć, odprysków i nieszczelności.',{family:'glass'});
P('rear-glass','Szyba tylna','body','Zamyka tył kabiny. Przewodzące ścieżki ogrzewania pomagają usunąć zaparowanie i szron.','Tylna szyba pozostaje na miejscu podczas otwierania pokrywy bagażnika.','Sprawdź uszczelnienie i działanie ogrzewania.',{family:'glass'});
P('fuel-flap','Klapka wlewu','body','Osłania dostęp do korka zbiornika. Klapka i korek są dwoma odrębnymi elementami.','Otwórz klapkę, a następnie wybierz korek wlewu.','Sprawdź blokadę i zawias.',{family:'fuel',motion:'Otwórz / zamknij klapkę'});
P('fuel-cap','Korek paliwa','fuel','Uszczelnia wlew i współpracuje z kontrolowanym odpowietrzaniem zbiornika.','Obróć i odsuń korek. W modelu nie występuje wyciek ani ciśnienie paliwa.','Obejrzyj uszczelkę i stan gwintu.',{family:'fuel',motion:'Odkręć / zakręć korek'});
for(const [s,label] of [['l','lewy'],['r','prawy']]){
  P('front-fender-'+s,'Błotnik przedni · '+label,'body','Otacza przednie koło i tworzy krawędź komory silnika. Poszycie błotnika jest oddzielone od elementów prowadzących koło.','Odsuń błotnik, by zobaczyć kolumnę zawieszenia i nadkole.','Obejrzyj korozję, mocowania i spasowanie.',{family:'panels'});
  P('rear-quarter-'+s,'Błotnik tylny · '+label,'body','Boczna część nadwozia otacza tylne koło oraz bagażnik. W realnym aucie jest zwykle trwale połączona z konstrukcją.','Odsuwanie jest wyłącznie przekrojem dydaktycznym, nie instrukcją demontażu.','Obejrzyj rant nadkola i ślady napraw.',{family:'panels'});
  P('mirror-'+s,'Lusterko · '+label,'body','Pozwala obserwować przestrzeń obok auta. Obudowa, wkład i mocowanie są odrębnymi częściami zespołu.','Złóż lusterko na jego mocowaniu. Podąża ono także za otwieranymi drzwiami.','Sprawdź szkło, regulację i stabilność.',{family:'glass',motion:'Złóż / rozłóż lusterko'});
  P('headlamp-'+s,'Reflektor · '+label,'body','Układ optyczny kieruje światło na drogę. Przez klosz widać odbłyśniki oraz źródła światła.','Przełącz światła. Zmienia się emisja źródeł, nie położenie samochodu.','Oceń przejrzystość klosza, mocowania i działanie.',{family:'lighting',motion:'Włącz / wyłącz światło'});
  P('tail-lamp-'+s,'Lampa tylna · '+label,'body','Pozycyjne i hamowania informują o położeniu auta i hamowaniu. Kierunkowskaz sygnalizuje zmianę kierunku.','Włącz lampę lub naciśnij w modelu pedał hamulca, aby zobaczyć światło STOP.','Przetestuj funkcje i szczelność.',{family:'lighting',motion:'Włącz / wyłącz lampę'});
  P('wiper-'+s,'Wycieraczka · '+label,'body','Silnik i przekładnia poruszają ramieniem, a gumowe pióro zbiera wodę z szyby.','Uruchom ruch wahadłowy. Ramię obraca się wokół mocowania w podszybiu.','Sprawdź pióro, docisk i zakres pracy.',{family:'glass',motion:'Uruchom / zatrzymaj wycieraczkę'});
  for(const [a,axle] of [['f','przód'],['b','tył']]){
    const suffix=s+a,side=s==='l'?'lewe':'prawe';
    P('door-'+suffix,'Drzwi · '+side+' '+axle,'body','Poszycie, rama i zamek tworzą dostęp do kabiny. Szyba oraz tapicerka mają w modelu osobne pozycje.','Otwórz te drzwi niezależnie od pozostałych. Szyba, tapicerka i lusterko podążają za zawiasem.','Sprawdź zamykanie, uszczelki i dolne krawędzie.',{family:'door-'+suffix,motion:'Otwórz / zamknij drzwi'});
    P('window-'+suffix,'Szyba drzwi · '+side+' '+axle,'body','Podnośnik przesuwa szybę po prowadnicach wewnątrz drzwi.','Opuść szybę. Ruch działa również przy otwartych drzwiach.','Sprawdź płynność i uszczelnienie.',{family:'door-'+suffix,motion:'Opuść / podnieś szybę'});
    P('door-card-'+suffix,'Tapicerka drzwi · '+side+' '+axle,'cabin','Wewnętrzny panel osłania mechanizmy i wiązki oraz mieści uchwyt i przełączniki.','Odsuń panel, aby odróżnić go od lakierowanego poszycia.','Sprawdź mocowania, zawilgocenie i przyciski.',{family:'door-'+suffix});
  }
}
const E=(...a)=>P(...a);
E('engine-cover','Osłona silnika','engine','Osłona porządkuje wygląd komory i może ograniczać hałas. Nie jest blokiem ani pokrywą zaworów.','Odsuń ją, aby odsłonić cewki i głowicę.','Obejrzyj mocowania i ślady płynów.',{family:'top-engine'});
E('cam-cover','Pokrywa zaworów','engine','Uszczelnia górę głowicy i zatrzymuje olej przy mechanizmie rozrządu.','Odsunięcie odsłania wałki rozrządu i zawory w przekroju.','Szukaj wycieków przy uszczelce.',{family:'top-engine'});
E('head','Głowica','engine','Mieści zawory, kanały dolotowe i wydechowe oraz komory spalania. Z blokiem łączy ją uszczelka głowicy.','Widok mechanizmu usuwa przesłaniające ściany, aby pokazać zawory nad tłokami.','Powtarzające się ubytki płynów lub przegrzewanie wymagają diagnozy.',{family:'top-engine'});
E('block','Blok silnika','engine','Prowadzi tłoki w cylindrach i podpiera wał korbowy. Płaszcz chłodzący oraz kanały olejowe biegną wewnątrz odlewu.','Widok mechanizmu pokazuje przekrój, nie przezroczysty materiał prawdziwego bloku.','Obejrzyj wycieki i uszkodzenia odlewu.',{family:'bottom-engine'});
E('oil-pan','Miska olejowa','engine','Gromadzi olej spływający z silnika. Smok pompy pobiera stąd olej do obiegu smarowania.','Odsuń miskę od dołu, aby zobaczyć wał i pompę.','Sprawdź wgniecenia i wycieki.',{family:'lubrication'});
E('oil-cap','Korek wlewu oleju','engine','Zamyka otwór służący do uzupełniania oleju silnikowego.','Odkręcanie jest ilustracją. Dobór oleju i sposób pomiaru określa instrukcja rzeczywistego auta.','Obejrzyj uszczelkę i ślady wycieku.',{family:'lubrication',motion:'Odkręć / zakręć korek'});
E('dipstick','Bagnet oleju','engine','Pozwala ocenić poziom oleju w misce. Nie mierzy jego ciśnienia ani jakości.','Wyciągnij bagnet pionowo z prowadnicy.','Poziom sprawdzaj zgodnie z instrukcją i na równym podłożu.',{family:'lubrication',motion:'Wyciągnij / włóż bagnet'});
E('oil-filter','Filtr oleju','engine','Zatrzymuje zanieczyszczenia w obiegu smarowania, zanim olej wróci do wrażliwych elementów.','Odsuń filtr, aby zobaczyć jego położenie przy bloku.','Sprawdź wycieki i historię wymian.',{family:'lubrication'});
E('oil-pump','Pompa oleju','engine','Wytwarza przepływ w układzie smarowania. Ciśnienie zależy także od oporów obiegu i stanu silnika.','Pompa znajduje się nisko, przy wale i smoku w misce.','Kontrolka ciśnienia oleju wymaga ustalenia przyczyny.',{family:'lubrication'});
E('timing-cover','Osłona rozrządu','engine','Chroni pasek i koła rozrządu przed zabrudzeniami.','Odsuń osłonę lub wybierz mechanizm, aby zobaczyć przełożenie 2:1.','Sprawdź kompletność i ślady oleju.',{family:'timing'});
E('timing-belt','Pasek rozrządu','engine','Synchronizuje wał korbowy z wałkami rozrządu. W silniku czterosuwowym wałki obracają się dwa razy wolniej od wału.','Uruchom mechanizm: na dwa obroty wału przypada jeden obrót wałków.','Wiek i przebieg wymiany potwierdzaj dokumentacją.',{family:'timing',motion:'Uruchom / zatrzymaj mechanizm'});
E('tensioner','Napinacz rozrządu','engine','Utrzymuje odpowiednie napięcie paska i pomaga stabilnie prowadzić go po kołach.','Odsuń rolkę, aby odróżnić ją od napędzanego koła wałka.','Stan zestawu ocenia się zgodnie z procedurą serwisową.',{family:'timing'});
E('accessory-belt','Pasek osprzętu','engine','Przenosi napęd z wału na osprzęt, np. alternator i sprężarkę klimatyzacji. To inny pasek niż rozrząd.','W modelu zaznaczono wspólny obieg po stronie przeciwnej do skrzyni.','Obejrzyj pęknięcia, zabrudzenie i pracę rolek.',{family:'accessories'});
E('alternator','Alternator','engine','Zamienia energię mechaniczną na elektryczną i ładuje akumulator podczas pracy silnika.','Uruchom obrót koła pasowego. To demonstracja wirnika, bez symulacji prądu.','Sprawdź ładowanie, pasek i przewody.',{family:'accessories',motion:'Obracaj / zatrzymaj koło'});
E('starter','Rozrusznik','engine','Silnik elektryczny obraca wał podczas uruchamiania, zazębiając się z wieńcem koła zamachowego.','Odsuń rozrusznik przy połączeniu silnika ze skrzynią.','Zwróć uwagę na prędkość rozruchu i nietypowe odgłosy.',{family:'accessories'});
E('water-pump','Pompa płynu chłodzącego','engine','Wymusza obieg płynu przez silnik i wymienniki ciepła.','W przyjętej architekturze pompa jest napędzana rozrządem.','Szukaj śladów wycieku i potwierdź obsługę.',{family:'cooling'});
E('thermostat','Termostat','engine','Kieruje przepływem płynu zależnie od temperatury, pomagając silnikowi osiągnąć i utrzymać temperaturę pracy.','Obudowa łączy silnik z przewodami układu chłodzenia.','Wahania temperatury wymagają ustalenia przyczyny.',{family:'cooling'});
E('radiator','Chłodnica silnika','engine','Oddaje ciepło płynu do przepływającego powietrza. Cienkie lamele zwiększają powierzchnię wymiany ciepła.','Odsuń przedni zderzak lub wyizoluj chłodnicę.','Obejrzyj lamele, zbiorniki i połączenia.',{family:'cooling'});
for(const s of ['l','r'])E('fan-'+s,'Wentylator chłodnicy · '+(s==='l'?'lewy':'prawy'),'engine','Wymusza przepływ powietrza przez chłodnicę przy małej prędkości auta lub wysokim zapotrzebowaniu na chłodzenie.','Uruchom pojedynczy wirnik. Auto pozostaje nieruchome.','Sprawdzenie elektryczne i temperaturę pracy zleć warsztatowi.',{family:'cooling',motion:'Włącz / wyłącz wentylator',tip:'W rzeczywistym aucie wentylator może włączyć się samoczynnie. Nie wkładaj rąk w jego obszar.'});
E('coolant-tank','Zbiornik wyrównawczy','engine','Kompensuje zmianę objętości płynu chłodzącego i umożliwia ocenę jego poziomu.','Osobno wybierz korek zamykający układ pod ciśnieniem.','Sprawdź poziom przy zimnym silniku i ślady ubytków.',{family:'cooling'});
E('coolant-cap','Korek układu chłodzenia','engine','Uszczelnia zbiornik i zawiera zawory regulujące ciśnienie układu.','Obrót korka w modelu jest wyłącznie wizualizacją.','Obejrzyj szczelność i stan zbiornika.',{family:'cooling',motion:'Odkręć / zakręć korek',tip:'Nie odkręcaj korka rozgrzanego układu. Gorący płyn pod ciśnieniem może poparzyć.'});
E('washer-tank','Zbiornik spryskiwaczy','engine','Przechowuje płyn podawany pompką do dysz przedniej szyby.','Zbiornik i niebieski korek są osobnymi obiektami.','Przetestuj dysze i sprawdź wycieki.',{family:'glass'});
E('washer-cap','Korek spryskiwaczy','engine','Zamyka wlew płynu do spryskiwaczy. Symbol na korku jest ważniejszy niż jego kolor.','Unieś korek na zawiasie.','Nie pomyl zbiornika z układem chłodzenia.',{family:'glass',motion:'Otwórz / zamknij korek'});
E('battery','Akumulator 12 V','engine','Magazynuje energię do rozruchu i zasila odbiorniki, gdy silnik nie pracuje.','Odsuń całą bryłę, aby obejrzeć mocowanie i bieguny.','Obejrzyj obudowę i klemy; sprawność potwierdza test.',{family:'electrical',tip:'Nie zwieraj biegunów i nie odłączaj akumulatora przy pracującym silniku.'});
E('fusebox','Skrzynka bezpieczników','engine','Bezpieczniki chronią przewody przed nadmiernym prądem. Przekaźniki mogą załączać większe odbiorniki.','Podnieś pokrywę skrzynki. Kolorowe wkładki pozostają widoczne w środku.','Ustal przyczynę przepalania; nie zwiększaj wartości bezpiecznika.',{family:'electrical',motion:'Otwórz / zamknij pokrywę'});
E('ecu','Sterownik silnika ECU','engine','Przetwarza sygnały czujników i steruje m.in. dawką paliwa, zapłonem oraz przepustnicą.','Wiązka łączy sterownik z czujnikami i elementami wykonawczymi.','Diagnostykę oprzyj na kodach błędów i pomiarach.',{family:'electrical'});
E('airbox','Obudowa filtra powietrza','engine','Uszczelnia dopływ oczyszczonego powietrza. Jej pokrywa zapewnia dostęp do wkładu filtra.','Otwórz pokrywę, a następnie odsuń osobny wkład.','Sprawdź szczelność i mocowania.',{family:'intake',motion:'Otwórz / zamknij obudowę'});
E('air-filter','Wkład filtra powietrza','engine','Fałdowany materiał zatrzymuje pył, zanim powietrze trafi do silnika.','Wyjmij wkład z otwartej obudowy.','Sprawdź stan i historię wymiany.',{family:'intake'});
E('throttle','Przepustnica elektroniczna','engine','Motylkowa klapa reguluje ilość powietrza docierającego do silnika. Steruje nią ECU.','Porusz pedałem gazu albo samą przepustnicą. Widać obrót klapy w gardzieli.','Nierówne obroty wymagają diagnostyki całego dolotu.',{family:'intake',motion:'Otwórz / zamknij przepustnicę'});
E('intake','Kolektor dolotowy','engine','Rozdziela powietrze na cztery kanały prowadzące do zaworów dolotowych.','Cztery zakrzywione kanały odpowiadają czterem cylindrom. Wtryskiwacze MPI podają paliwo przed zaworami.','Szukaj nieszczelności i uszkodzeń przewodów.',{family:'intake'});
E('fuel-rail','Listwa wtryskowa MPI','engine','Dostarcza benzynę do czterech wtryskiwaczy. Wtrysk pośredni tworzy mieszankę przed komorą spalania.','Porównaj listwę z umieszczonymi pod nią wtryskiwaczami.','Zapach paliwa lub wyciek wymaga ustalenia przyczyny.',{family:'injection'});
for(const [id,n,d,how] of [
 ['map','Czujnik MAP','Mierzy ciśnienie w kolektorze dolotowym. ECU wykorzystuje je do oceny obciążenia.','Zwróć uwagę na połączenie czujnika z kolektorem.'],
 ['ckp','Czujnik wału','Informuje sterownik o położeniu i prędkości wału korbowego.','Odczytuje znacznik przy kole wału; nie napędza wału.'],
 ['cmp','Czujnik wałka','Pomaga ECU rozpoznać fazę cyklu silnika na podstawie położenia wałka rozrządu.','Wałek obraca się o połowę wolniej od wału.'],
 ['knock','Czujnik spalania stukowego','Rejestruje charakterystyczne drgania bloku, umożliwiając korektę sterowania zapłonem.','Jest zamocowany do bloku, aby odbierać jego drgania.'],
 ['temperature','Czujnik temperatury płynu','Dostarcza informację o temperaturze do sterowania mieszanką, chłodzeniem i wskazaniami.','Czujnik jest przy obiegu płynu; nie zastępuje termostatu.']
])E(id,n,'engine',d,how,'Złącza, przewody i odczyty sprawdzaj podczas diagnostyki.',{family:'electrical'});
P('crankshaft','Wał korbowy','internals','Zamienia posuwisty ruch tłoków w obrót. Czopy korbowe są przesunięte względem osi wału.','Uruchom przekrój lub przesuwaj kąt cyklu. Widać ruch czopów i połączonych z nimi korbowodów.','Jego stanu nie ocenia się przez samą obserwację zewnętrzną.',{family:'crank',motion:'Uruchom / zatrzymaj mechanizm'});
for(const [id,n] of [['cam-in','Wałek dolotowy'],['cam-ex','Wałek wydechowy']])P(id,n,'internals','Krzywki otwierają odpowiednią grupę zaworów. Obrót wałka jest zsynchronizowany z wałem korbowym.','W modelu wałek wykonuje jeden obrót na 720° obrotu wału. Profil krzywek i fazy są uproszczone.','Luzy, smarowanie i fazy sprawdza się według dokumentacji silnika.',{family:'timing',motion:'Uruchom / zatrzymaj mechanizm'});
for(let i=1;i<=4;i++){
  P('piston-'+i,'Tłok · cylinder '+i,'internals','Przesuwa się w cylindrze, sprężając mieszankę i odbierając siłę rozprężających się gazów. Pierścienie ograniczają przedmuchy i kontrolują olej.','Obserwuj suwy: dolot, sprężanie, praca, wydech. Korbowód łączy sworzeń tłoka z wałem.','Zużycie ocenia się pomiarami i diagnostyką, nie z samego dźwięku.',{family:'cylinder-'+i,motion:'Uruchom / zatrzymaj mechanizm',cylinder:i});
  P('rod-'+i,'Korbowód · cylinder '+i,'internals','Przenosi siły między tłokiem a czopem korbowym. Jego oba końce mają połączenia obrotowe.','W animacji długość korbowodu jest stała, a zmieniają się jego położenie i kąt.','Luzów łożyskowania nie ocenia się z widoku zewnętrznego.',{family:'cylinder-'+i,motion:'Uruchom / zatrzymaj mechanizm',cylinder:i});
  P('coil-'+i,'Cewka · cylinder '+i,'engine','Wytwarza impuls wysokiego napięcia potrzebny do przeskoku iskry na świecy.','Cewka typu pencil jest umieszczona bezpośrednio przy świecy. Odsuń ją, aby zobaczyć osobną świecę.','Wypadanie zapłonów potwierdź diagnostyką.',{family:'cylinder-'+i});
  P('spark-'+i,'Świeca · cylinder '+i,'engine','Elektrody świecy wytwarzają iskrę zapalającą sprężoną mieszankę benzyny i powietrza.','W przekroju impuls oznaczono światłem przy końcu świecy. To schemat chwili zapłonu.','Dobór i stan świec oceń według dokumentacji.',{family:'cylinder-'+i});
  P('injector-'+i,'Wtryskiwacz MPI · '+i,'engine','Dawkuje benzynę do kanału dolotowego przed zaworem, a nie bezpośrednio do cylindra.','Jest podłączony do wspólnej listwy paliwa. Mieszanka wpływa do cylindra podczas dolotu.','Nieszczelność i dawkowanie wymagają odpowiednich testów.',{family:'cylinder-'+i});
  for(const type of ['in','ex'])for(let j=1;j<=2;j++)P(`valve-${type}-${i}-${j}`,`Zawór ${type==='in'?'dolotowy':'wydechowy'} · ${i}.${j}`,'internals',type==='in'?'Otwiera drogę mieszanki z kanału dolotowego do cylindra. Sprężyna przywraca zawór do gniazda.':'Otwiera drogę spalin z cylindra do kolektora wydechowego. Sprężyna zamyka go po zejściu krzywki.','Każdy z czterech cylindrów ma dwa zawory dolotowe i dwa wydechowe: razem 16. Ruch można obejrzeć w cyklu 720°.','Szczelność, luzy i fazy wymagają pomiarów.',{family:'cylinder-'+i,motion:'Uruchom / zatrzymaj mechanizm',cylinder:i,valveType:type});
}

P('dashboard','Deska rozdzielcza','cabin','Mieści przyrządy, kanały nawiewu i wyposażenie kabiny. Nie jest jednolitą bryłą konstrukcyjną.','Odsuń deskę, by rozróżnić klimatyzację, schowek i instalację za nią.','Sprawdź mocowania i funkcje wyposażenia.',{family:'cockpit'});
P('cluster','Zestaw wskaźników','cabin','Prezentuje m.in. prędkość, obroty i kontrolki. Niektóre kontrolki sygnalizują stan, inne usterkę.','Podczas demonstracji silnika wskazanie obrotów jest umowne, bo pojazd nie jedzie.','Obserwuj test kontrolek i komunikaty.',{family:'cockpit'});
P('screen','Ekran multimediów','cabin','Wyświetla informacje i pozwala obsługiwać funkcje komfortowe. Nie steruje mechanicznie układem kierowniczym ani hamulcami.','Przełącz demonstracyjny ekran z mapy na informacje auta.','Sprawdź ekran, przyciski i dźwięk.',{family:'cockpit',motion:'Przełącz ekran'});
P('steering-wheel','Kierownica','cabin','Przekazuje ruch kierowcy przez kolumnę i przekładnię do drążków oraz zwrotnic.','Przesuwaj sterowanie skrętem. Oba przednie koła skręcają, a koło wewnętrzne nieco mocniej.','Luzy i nieprawidłowe opory wymagają sprawdzenia.',{family:'steering',motion:'Skręt kierownicy',neutral:.5});
P('hvac','Zespół nawiewu i nagrzewnicy','cabin','Rozprowadza powietrze, ogrzewa je w nagrzewnicy i chłodzi oraz osusza przy parowniku klimatyzacji.','Znajduje się za deską, w okolicy grodzi. Wybierz izolację, aby obejrzeć bryłę wymienników.','Sprawdź nadmuch, temperaturę i zapach.',{family:'climate'});
P('climate-controls','Panel klimatyzacji','cabin','Pozwala zadawać temperaturę, siłę i kierunek nawiewu.','Przełącz podświetlenie panelu. Nie symuluje to termodynamiki klimatyzacji.','Sprawdź wszystkie pokrętła i przyciski.',{family:'climate',motion:'Włącz / wyłącz panel'});
P('cabin-filter','Filtr kabinowy','cabin','Oczyszcza powietrze płynące do kabiny. To inny filtr niż wkład powietrza silnika.','Wysuń go spod deski.','Zapytaj o wymianę; ograniczony nadmuch ma też inne przyczyny.',{family:'climate'});
P('glovebox','Schowek pasażera','cabin','Zamykany pojemnik w desce przed pasażerem. Pokrywa obraca się na dolnym zawiasie.','Otwórz schowek i zajrzyj do wnętrza.','Sprawdź zamek i zawiasy.',{family:'cockpit',motion:'Otwórz / zamknij schowek'});
P('gear-lever','Dźwignia zmiany biegów','cabin','Przekazuje wybór przełożenia do skrzyni poprzez mechanizm wybierania.','Porusz dźwignią w uproszczonym zakresie wybieraka.','Sprawdź wybieranie biegów podczas odpowiedniej próby.',{family:'transmission',motion:'Porusz dźwignią'});
P('handbrake','Dźwignia hamulca postojowego','cabin','Mechaniczny hamulec postojowy w tym projekcie oddziałuje na tylną oś za pomocą linek.','Unieś dźwignię. Ten ruch jest niezależny od hydraulicznego pedału hamulca.','Skuteczność potwierdź na bezpiecznym stanowisku.',{family:'brakes',motion:'Zaciągnij / zwolnij hamulec'});
for(const [id,n,d] of [['gas-pedal','Pedał gazu','Czujnik pedału przekazuje ECU żądanie obciążenia. Sterownik ustawia elektroniczną przepustnicę.'],['brake-pedal','Pedał hamulca','Uruchamia pompę hamulcową, która wytwarza ciśnienie w obwodach hamulcowych.'],['clutch-pedal','Pedał sprzęgła','Uruchamia wysprzęglanie, rozłączając przenoszenie momentu pomiędzy silnikiem a skrzynią.']])P(id,n,'cabin',d,'Naciśnij pedał suwakiem. Obserwuj połączony mechanizm: przepustnicę, zaciski lub sprzęgło.','Sprawdź płynny ruch i nieprawidłowe opory.',{family:id==='gas-pedal'?'intake':id==='brake-pedal'?'brakes':'transmission',motion:'Naciśnij / zwolnij pedał'});
for(const [s,label] of [['l','kierowcy'],['r','pasażera']]){
  P('seat-'+s,'Siedzisko '+label,'cabin','Prowadnice umożliwiają ustawienie fotela względem pedałów i pasów.','Przesuń fotel wzdłuż prowadnic. Oparcie i zagłówek podążają razem z siedziskiem.','Sprawdź blokadę położenia i luzy.',{family:'seat-'+s,motion:'Przesuń fotel'});
  P('seat-back-'+s,'Oparcie '+label,'cabin','Podpiera tułów i zmienia pochylenie względem siedziska.','Odchyl oparcie na dolnym zawiasie.','Sprawdź stabilność regulacji.',{family:'seat-'+s,motion:'Odchyl oparcie'});
  P('headrest-'+s,'Zagłówek '+label,'cabin','Ogranicza względny ruch głowy i tułowia przy uderzeniu od tyłu.','Podnieś zagłówek na dwóch prowadnicach.','Sprawdź regulację i blokadę.',{family:'seat-'+s,motion:'Podnieś / opuść zagłówek'});
  P('belt-'+s,'Pas przedni · '+label,'cabin','Taśma, zwijacz i klamra utrzymują pasażera na fotelu. Pasy współpracują z pozostałymi zabezpieczeniami.','Odsuń zespół, aby rozróżnić pas i fotel.','Obejrzyj taśmę, zwijanie oraz zamek.',{family:'seat-'+s});
  P('visor-'+s,'Osłona przeciwsłoneczna · '+label,'cabin','Ogranicza oślepianie przez nisko położone słońce.','Opuść osłonę z położenia przy podsufitce.','Sprawdź zawias i utrzymywanie pozycji.',{family:'cockpit',motion:'Opuść / podnieś osłonę'});
}
P('rear-seat','Siedzisko tylnej kanapy','cabin','Podpiera pasażerów z tyłu i osłania przestrzeń pod kanapą.','Odsuń siedzisko, aby zobaczyć jego oddzielenie od oparć.','Sprawdź mocowania i wilgoć.',{family:'rear-seat'});
for(const [s,n] of [['l','lewa'],['r','prawa']])P('rear-back-'+s,'Oparcie kanapy · '+n+' część','cabin','Dzielone oparcie pozwala połączyć część kabiny z bagażnikiem.','Złóż tę część niezależnie, pozostawiając drugą na miejscu.','Sprawdź rygle i mocowania.',{family:'rear-seat',motion:'Złóż / podnieś oparcie'});
P('boot-floor','Podłoga bagażnika','cabin','Oddziela przestrzeń ładunkową od wnęki koła zapasowego.','Unieś panel na tylnym zawiasie, a następnie wybierz koło zapasowe.','Sprawdź wilgoć i ślady napraw we wnęce.',{family:'luggage',motion:'Unieś / opuść podłogę'});
P('spare','Koło zapasowe','cabin','Umożliwia zastąpienie uszkodzonego koła, zgodnie z ograniczeniami danego zestawu.','Odsuń je pionowo z wnęki pod podłogą.','Sprawdź stan, ciśnienie i wyposażenie awaryjne.',{family:'luggage'});

for(const [c,side,axle] of [['lf','lewy','przód'],['rf','prawy','przód'],['lb','lewy','tył'],['rb','prawy','tył']]){
  const suffix=` · ${side} ${axle}`;
  for(const [key,n,d,h,f] of [
    ['tire','Opona','Przenosi siły hamowania, napędu i skrętu na nawierzchnię.','Odsuń samą oponę albo wybierz felgę osobno.','wheels'],
    ['rim','Felga','Podpiera oponę i mocuje koło do piasty za pomocą śrub.','Możesz odsunąć felgę niezależnie od opony.','wheels'],
    ['rotor','Tarcza hamulcowa','Obraca się z kołem, a klocki zamieniają energię ruchu w ciepło przez tarcie.','Naciśnij pedał hamulca i obserwuj zbliżanie klocków do obu stron tarczy.','brakes'],
    ['caliper','Zacisk','Mieści tłoczek i prowadzi klocki przy tarczy. Ciśnienie płynu wywołuje siłę docisku.','Po odsunięciu koła zobaczysz zacisk pozostający nieruchomo względem zwrotnicy.','brakes'],
    ['pads','Klocki hamulcowe','Dwie okładziny cierne dociskają tarczę z obu stron.','Przy naciskaniu hamulca ich widoczny skok jest w modelu powiększony dla czytelności.','brakes'],
    ['hub','Piasta z łożyskiem','Podpiera obracające się koło i utrzymuje jego oś względem zwrotnicy.','Odsuń koło i tarczę, aby zobaczyć piastę.','wheels'],
    ['knuckle',axle==='przód'?'Zwrotnica':'Nośnik piasty','Łączy piastę z elementami prowadzącymi zawieszenie.','Z przodu obraca się przy skręcie; z tyłu podtrzymuje piastę w układzie wielowahaczowym.','suspension'],
    ['spring','Sprężyna','Podtrzymuje masę nadwozia i magazynuje energię przy ugięciu zawieszenia.','Ściśnij sprężynę suwakiem. To ilustracja ugięcia, bez symulacji całego pojazdu.','suspension'],
    ['damper','Amortyzator','Tłumi ruchy zawieszenia, rozpraszając energię. Nie pełni tej samej funkcji co sprężyna.','Porusz tłoczyskiem. Widok pokazuje kierunek pracy, bez hydrauliki wewnętrznej.','suspension'],
    ['arm',axle==='przód'?'Wahacz dolny':'Wahacz poprzeczny','Prowadzi koło względem ramy pomocniczej, współpracując ze sworzniami i tulejami.','Odsuń wahacz i prześledź jego połączenia z podwoziem oraz nośnikiem piasty.','suspension']
  ])P(key+'-'+c,n+suffix,'chassis',d,h,'Sprawdź uszkodzenia, zużycie i mocowania.|Luzy i skuteczność oceń na właściwym stanowisku.',{family:f,corner:c,motion:key==='spring'?'Ściśnij / rozpręż sprężynę':key==='damper'?'Porusz tłoczyskiem':key==='caliper'||key==='pads'?'Zaciśnij / zwolnij hamulec':key==='knuckle'&&axle==='przód'?'Skręt kół':undefined,neutral:key==='knuckle'&&axle==='przód'?.5:0});
}
for(const s of ['l','r']){
  P('tie-rod-'+s,'Drążek kierowniczy · '+(s==='l'?'lewy':'prawy'),'chassis','Przenosi ruch przekładni kierowniczej na ramię zwrotnicy. Końcówka ma połączenie przegubowe.','Skręć kierownicę i prześledź połączenie do przedniego koła.','Luzy wymagają oceny warsztatowej.',{family:'steering',motion:'Skręt kół',neutral:.5});
  P('upper-arm-'+s,'Wahacz tylny górny · '+(s==='l'?'lewy':'prawy'),'chassis','Jeden z oddzielnych elementów prowadzących koło w tylnym układzie wielowahaczowym.','Porównaj jego położenie z dolnym wahaczem i ramieniem wzdłużnym.','Sprawdź tuleje, uszkodzenia i geometrię.',{family:'suspension'});
  P('trailing-arm-'+s,'Wahacz tylny wzdłużny · '+(s==='l'?'lewy':'prawy'),'chassis','Przenosi obciążenia wzdłużne i współpracuje z wahaczami poprzecznymi.','W modelu biegnie od okolicy przed tylnym kołem do nośnika piasty.','Sprawdź tuleje oraz korozję.',{family:'suspension'});
  P('halfshaft-'+s,'Półoś napędowa · '+(s==='l'?'lewa':'prawa'),'chassis','Przekazuje moment z mechanizmu różnicowego na przednie koło.','W tym projekcie napędzane są wyłącznie koła przednie.','Sprawdź osłony, wycieki smaru i nietypowe odgłosy.',{family:'transmission'});
  for(const k of ['inner','outer'])P('cv-'+s+'-'+k,'Przegub '+(k==='inner'?'wewnętrzny':'zewnętrzny')+' · '+(s==='l'?'lewy':'prawy'),'chassis','Pozwala przekazywać napęd mimo zmiany kąta półosi. Gumowa osłona zatrzymuje smar.','Zewnętrzny przegub jest przy kole, a wewnętrzny przy skrzyni.','Pęknięcia osłon i utrata smaru wymagają naprawy.',{family:'transmission'});
}
for(const [id,n,d,h,f] of [
 ['rack','Przekładnia kierownicza','Zamienia obrót kolumny w przesuw drążków kierowniczych.','Skręć kierownicę i obserwuj położenie drążków.','steering'],
 ['front-subframe','Rama pomocnicza przednia','Stanowi punkt mocowania wahaczy i części zespołu napędowego.','Oddziel ją od podłogi, aby zobaczyć strukturę mocowań.','suspension'],
 ['rear-subframe','Rama pomocnicza tylna','Łączy tylne wahacze z nadwoziem przez punkty mocowania.','Obejrzyj połączenia układu wielowahaczowego.','suspension'],
 ['brake-booster','Serwo hamulcowe','Zmniejsza siłę potrzebną na pedale, wspomagając pracę pompy.','W tym modelu to podciśnieniowa puszka przed pompą.','brakes'],
 ['master-cylinder','Pompa hamulcowa','Zamienia nacisk z pedału na ciśnienie w obwodach hydraulicznych.','Prześledź drogę od pedału przez serwo do pompy.','brakes'],
 ['brake-reservoir','Zbiornik płynu hamulcowego','Zapewnia rezerwę płynu dla układu hydraulicznego.','Poziom ocenia się przez ściankę, bez otwierania przy oględzinach.','brakes'],
 ['abs','Blok hydrauliczny ABS','Moduluje ciśnienie w obwodach kół, aby ograniczać ich blokowanie.','Osobne przewody prowadzą do poszczególnych hamulców.','brakes'],
 ['brake-lines','Przewody hamulcowe','Przenoszą ciśnienie płynu między pompą, blokiem ABS i zaciskami.','Odsuń zespół przewodów, aby prześledzić ich przebieg.','brakes'],
 ['gearbox','Skrzynia manualna','Dobiera przełożenie pomiędzy silnikiem a napędem kół.','Obudowa mieści wałki i koła zębate; ich zazębienie jest uproszczone w tym modelu.','transmission'],
 ['flywheel','Koło zamachowe','Wygładza pulsacje momentu i udostępnia powierzchnię współpracy ze sprzęgłem.','Obraca się razem z wałem; przy wieńcu pracuje rozrusznik.','transmission'],
 ['clutch','Sprzęgło','Dociska tarczę cierną do koła zamachowego, umożliwiając przekazywanie momentu do skrzyni.','Naciśnij sprzęgło: pokazano umowne rozdzielenie powierzchni ciernych.','transmission'],
 ['differential','Mechanizm różnicowy','Rozdziela napęd na obie półosie i pozwala kołom obracać się z różnymi prędkościami.','W napędzie przednim znajduje się przy skrzyni, nie przy tylnej osi.','transmission']
])P(id,n,'chassis',d,h,'Oceń wycieki, mocowania i objawy podczas diagnostyki.',{family:f,motion:id==='rack'?'Skręt kół':id==='clutch'?'Rozłącz / połącz sprzęgło':undefined,neutral:id==='rack'?.5:0});
for(const [id,n,d,h] of [
 ['tank','Zbiornik benzyny','Przechowuje paliwo i współpracuje z pompą oraz układem par paliwa.','Znajduje się pod tylną częścią podłogi, przed osią.'],
 ['fuel-pump','Moduł pompy paliwa','Tłoczy benzynę ze zbiornika do listwy wtryskowej.','Wyjmij moduł z górnego otworu zbiornika.'],
 ['fuel-lines','Przewód paliwowy','Prowadzi benzynę od pompy do komory silnika.','Porównaj go z osobnymi przewodami hamulcowymi i rurą wydechową.'],
 ['evap','Pochłaniacz par paliwa EVAP','Zatrzymuje pary benzyny na węglu aktywnym, a kontrolowane odpowietrzanie kieruje je do dolotu.','To układ par paliwa, a nie filtr cząstek stałych diesla.'],
 ['exhaust-manifold','Kolektor wydechowy','Zbiera spaliny z czterech cylindrów do wspólnego przewodu.','Cztery odgałęzienia zbiegają się po stronie wydechowej głowicy.'],
 ['catalyst','Katalizator trójdrożny','W odpowiednich warunkach ogranicza emisję tlenku węgla, węglowodorów i tlenków azotu.','Współpracuje ze sterowaniem mieszanką i sondami lambda.'],
 ['lambda-before','Sonda lambda przed katalizatorem','Ocenia zawartość tlenu w spalinach, wspierając regulację składu mieszanki.','Znajduje się przed katalizatorem. Nie mierzy poziomu benzyny.'],
 ['lambda-after','Sonda lambda za katalizatorem','Pomaga oceniać działanie katalizatora na podstawie tlenu w spalinach za nim.','Porównaj jej położenie z sondą przed katalizatorem.'],
 ['exhaust-pipe','Rura i tłumik środkowy','Prowadzi spaliny pod podłogą i ogranicza część hałasu.','Prześledź trasę od katalizatora do tylnego tłumika.'],
 ['rear-muffler','Tłumik końcowy','Ogranicza hałas przez komory i elementy tłumiące przepływ spalin.','To inny element niż katalizator.'],
 ['heat-shield','Osłona termiczna wydechu','Ogranicza przekazywanie ciepła do podłogi i sąsiednich instalacji.','Zwróć uwagę na odstęp między gorącą rurą a podłogą.']
])P(id,n,'fuel',d,h,'Obejrzyj uszkodzenia, mocowania oraz ślady nieszczelności.',{family:id.includes('fuel')||['tank','evap'].includes(id)?'fuel':'exhaust',tip:id.includes('lambda')||['catalyst','exhaust-manifold','exhaust-pipe','rear-muffler','heat-shield'].includes(id)?'Rzeczywisty układ wydechowy długo pozostaje gorący po wyłączeniu silnika.':'Zapach lub wyciek benzyny wymaga ustalenia przyczyny; unikaj źródeł zapłonu.'});
window.SEDAN_PARTS=parts.map((p,i)=>({...p,index:i+1,sub:cats[p.cat].toLowerCase(),point:[0,.7,0]}));window.SEDAN_CATEGORIES=cats;
})();
